import type { Node } from './types';
import type { Campaign } from '../state';
import { has } from '../state';
import type { Frag } from './novelReact';

const N = (text: string): Node => ({ t: 'narr', text });
const S = (who: string, text: string, tone?: string): Node => ({ t: 'say', who, text, tone });
const f = (id: string, at: string[] | undefined, when: Frag['when'], nodes: Node[], o: Partial<Frag> = {}): Frag => ({ id, at, when, nodes, ...o });
const H = (c: Campaign, ...fl: string[]) => fl.some(x => has(c, x));

/** Orden de las escenas de novela (claves de NOVEL). Un eco sólo puede sonar en una clave posterior al momento en que se decide. */
const K = ['cap0', 'cap1', 'cap2', 'm_cap3', 'm_cap4', 'acto2', 'm_cap6', 'm_cap7', 'm_cap8', 'm_cap9', 'acto3', 'm_cap11', 'm_cap12'];
/** Claves desde `a` hasta `b` (incluidas). */
const from = (a: string, b = 'm_cap12') => K.slice(K.indexOf(a), K.indexOf(b) + 1);

/**
 * Ecos: decisiones que antes no volvían a nombrarse. Se suman a los fragmentos de `novelReact.ts`.
 *  - `must` (una decisión con peso): suena en la primera escena de su lista en la que la bandera ya esté puesta.
 *  - ambiente: compite por `pri` con los demás fragmentos de ambiente de esa escena.
 * Notas de orden: las historias de arquetipo (`ARQ[k]`) se juegan DESPUÉS de la escena `k`, salvo `m_cap5`/`m_cap10`,
 * que van antes de las portadas `acto2`/`acto3`. Los interludios (noche1–4) se juegan en el mapa, tras la escena del capítulo.
 */
export const ECHO_FRAGS: Frag[] = [
  // ───────────────────────── Prólogo ─────────────────────────
  f('e_relieves', ['cap0', 'cap1'], c => has(c, 'estudio_relieves'), [N('Uno de ustedes todavía tiene polvo del relieve bajo las uñas. La espiral medio borrada del Simurg se le quedó en los dedos. Esa noche, sin darse cuenta, la repite en la arena junto al fuego. Por la mañana el viento la ha borrado. Y la ha vuelto a dibujar, un poco más lejos.')], { pri: 6 }),
  f('e_simbolo_zahir', ['cap1', 'cap2'], c => has(c, 'vio_simbolo_zahir'), [N('Alguien guardó en un pañuelo el puñado de arena que dejó el espectador, el que formaba el símbolo de Zahir. Cuando lo abre, días después, la arena ha cambiado de forma. Ahora es un ojo. No parpadea. Tampoco hace falta.')], { pri: 5 }),
  f('e_marcados', ['cap1'], c => has(c, 'marcados_por_razul'), [N('Esa noche, bajo la lámpara, el Vizir abrió la mano izquierda. En la palma le escocía la misma runa que había dibujado en el aire, seis veces, como seis puntos en un mapa de la ciudad. Cerró el puño. No dolía. Era la primera vez en años que algo le recordaba que tenía piel.')], { must: true }),
  f('e_hueso_djinn', ['cap2', 'm_cap3', 'm_cap4'], c => has(c, 'hueso_djinn'), [N('El hueso de djinn que les dio Zahir se calienta cuando pasan cerca de una lámpara del Conclave. Podrían mandar a un jann una vez al día. Nadie se atrevió todavía. Es fácil jurar que nunca usarán a un esclavo cuando el esclavo cabe en un bolsillo.')], { pri: 4 }),
  f('e_simurg_dividido', ['cap2', 'm_cap3', 'm_cap4'], c => has(c, 'sabe_simurg_dividido'), [N('Hay una frase de Zahir que no se les va: «la salvación de todos, empezando por la suya». La repiten de noche, como quien tantea un diente flojo con la lengua. Un dios que necesita salvarse primero. Nadie lo dice en voz alta. Todos lo pensaron con las mismas palabras.')], { pri: 5 }),

  // ───────────────────────── Aisha y Farid (Cap. II) ─────────────────────────
  f('e_aisha_devota', ['cap2'], c => has(c, 'aisha_devota'), [N('Aisha besa cada mañana el suelo donde ellos pisaron. Lo hace antes del pan, con la frente apoyada en el adobe. Farid la mira desde la estera y no entiende por qué su madre le reza a gente que come en su mesa. Ella tampoco lo entiende. Por eso reza.')], { must: true }),
  f('e_aisha_venganza', ['cap2'], c => H(c, 'aisha_venganza', 'tres_padres'), [N('Aisha guarda el frasco del Conclave en una caja de dátiles, envuelto en un trapo limpio. De noche lo saca para los tres padres que trajo. Lo ponen en el centro de la mesa y lo miran sin tocarlo, como se mira a un muerto en su velorio. No rezan. Hacen cuentas.')], { must: true }),
  f('e_aisha_maldice', ['cap2'], c => has(c, 'aisha_maldice'), [N('Aisha barre la biblioteca porque no tiene otro techo, y cocina para ellos porque no sabe cocinar para menos gente. Pero no los nombra. Cuando un vecino pregunta por los forasteros del cristal, escupe al costado y sigue amasando. En la estera, la sombra de Farid ya no se ríe. Espera.')], { must: true }),

  // ───────────────────────── Nadir (arquetipo, tras las Casas) ─────────────────────────
  f('e_nadir_mentor', ['m_cap4'], c => has(c, 'nadir_mentor'), [
    S('Nadir', 'Los rastros, les dije. Mi amigo los llamaba así. Murió buscando el que faltaba. Si lo encuentran, no lo toquen: escúchenlo. Era lo único que él sabía hacer bien.', 'en una taberna del Bajo, con un dedo en el borde del vaso'),
    N('Antes de irse les deja un pañuelo con un mapa cosido. Hay cuatro pilares marcados con hilo negro y un quinto, apenas, marcado con la uña.'),
  ], { must: true }),
  f('e_nadir_guia', ['m_cap4'], c => has(c, 'nadir_guia'), [N('Nadir gastó las veinte monedas en un camello cojo y un pasaje hacia el sur. Antes de irse preguntó en tres tabernas si alguien sabía de los pilares. Nadie sabía. Dejó dicho que, si unos forasteros con un cristal en el pecho preguntaban por él, les dijeran que el camino de vuelta también lo calculó dos veces.')], { must: true }),
  f('e_nadir_heraldo', ['m_cap4'], c => has(c, 'nadir_heraldo'), [N('En la Ciudadela, un escriba deja sobre la mesa del Vizir un informe de una línea: «El gnomo guía no cobró». Razul lo lee dos veces. Al margen, con su letra pequeña, escribe: «Que nadie le cobre a él tampoco». Es lo más parecido a un indulto que firmó en todo el año.')], { must: true }),

  // ───────────────────────── Cap. III ─────────────────────────
  f('e_shul_leal', ['m_cap4'], c => has(c, 'shul_leal'), [N('En el desierto del este, un efrit sin cadenas se sienta cada noche frente a una puerta que no existe y la guarda hasta el amanecer. Nadie se lo pide. Los nómadas que pasan le dejan leña. Él la enciende con un dedo y dice, a nadie: «Era esto».')], { must: true }),
  f('e_shul_recuerda', ['m_cap4'], c => has(c, 'shul_recuerda'), [N('La moneda de bronce con la llama grabada sigue clavada en la puerta de la biblioteca. Nadie la robó, y en el Bajo se roba todo. Cuando hace frío, la moneda está tibia. Los chicos apoyan la mano al pasar, como quien saluda a un perro viejo.')], { must: true }),
  f('e_sacrificio_recuerdo', ['m_cap3'], c => has(c, 'sacrificio_recuerdo'), [N('Esa noche, Al-Khush les cuenta con las manos una historia sobre una tarde feliz, de esas que todos tienen. Uno de ustedes se ríe en el lugar equivocado. Todos tienen una tarde así. Todos menos ustedes, ahora. Saben que existió. Ya no saben dónde la guardaban.')], { must: true }),
  f('e_sacrificio_voz', ['m_cap3'], c => has(c, 'sacrificio_voz'), [N('Pasaron un día entero sin voz y aprendieron cosas: que Panchi gesticula con todo el cuerpo, que Romain mueve los labios al rezar aunque no suene nada, que Zyr\'thar no extraña hablar. Cuando la voz volvió, tardaron una hora en usarla. Les daba un poco de vergüenza.')], { must: true }),
  f('e_sacrificio_rasgo', ['m_cap3'], c => has(c, 'sacrificio_rasgo'), [N('Algo se aflojó en el agua sólida y no vuelve. Nadie sabe decir qué. Aisha nota que uno de ustedes ya no tararea al lavarse las manos; que otro dejó de contar los escalones. Son cosas pequeñas. Son, también, la forma exacta de una persona.')], { must: true }),
  f('e_honro_alfombra', ['m_cap3'], c => has(c, 'honro_alfombra'), [N('Al-Khush guardó los hilos dorados chamuscados en una caja de cedro. No los teje. Cada tanto abre la caja y apoya la palma encima, como sobre el lomo de un animal dormido. No puede hablar. Pero cuando él los toca, los hilos se mueven un poco.')], { must: true }),
  f('e_alfombra_olvidada', ['m_cap3'], c => has(c, 'alfombra_sacrificada') && !has(c, 'honro_alfombra'), [N('Nadie recogió los hilos de la alfombra. Al-Khush bajó solo al acueducto con una linterna y volvió al amanecer con las manos vacías. No dijo nada, porque no puede. Esa semana no reparó ninguna alfombra, y en el Zoco se notó.')], { pri: 5 }),
  f('e_oraculo_resuelto', ['m_cap3', 'm_cap4'], c => has(c, 'oraculo_resuelto'), [N('El Oráculo dijo que no encontrarían nada donde lo buscaban, y lo encontraron. Desde entonces Rabb habla al revés cuando está de buen humor. «Qué día espantoso», dice, sonriendo. «Seguí, por favor», le contesta Panchi, que es su manera de pedirle que pare.')], { pri: 4 }),
  f('e_guanteletes', ['m_cap4', 'acto2', 'm_cap6'], c => has(c, 'guanteletes_ira'), [N('Panchi no se pone los Guanteletes de la Ira Rígida. Los lleva colgados del cinturón, golpeándole la cadera a cada paso. Dice que pesan. Lo que pesa es otra cosa: cada noche sueña con cadenas, y cada mañana se despierta con los puños cerrados y olor a ceniza.')], { pri: 5 }),
  f('e_linyera', ['m_cap4', 'acto2', 'm_cap6'], c => has(c, 'linyera_vivo'), [N('El Viejo Linyera sigue vivo. Lo vieron en la escalinata del Zoco, limpiando el mismo cuchillo oxidado. Cuando la compañía pasa, silba dos notas. Nadie sabe si es un saludo o un aviso. En Zaryab las paredes susurran; él, por lo menos, tiene la decencia de silbar.')], { pri: 3 }),

  // ───────────────────────── El Lago y los Hijos ─────────────────────────
  f('e_lago_purificado', from('m_cap3'), c => has(c, 'lago_purificado'), [N('El Lago de los Silencios refleja el cielo del derecho. Los Hijos del Simurg bajan a llenar cántaros y vuelven sin fiebre. En el Bajo, una madre le da a su hijo agua del lago sin hervirla, por primera vez, y se queda mirándolo beber como quien mira un milagro chico y sospechoso.')], { must: true }),
  f('e_lago_quemado', from('m_cap3'), c => has(c, 'lago_quemado'), [S('Vizir Razul', 'Humo violeta sobre el Bajo. Quemaron la rama. Entonces saben dónde enfermó el niño. Anotá, escriba: «Ya no son ignorantes». Es la peor noticia que podías traerme esta semana.', 'desde la ventana de la torre, sin volverse')], { must: true }),
  f('e_prueba_rama', from('m_cap3'), c => has(c, 'prueba_rama'), [N('La astilla negra de la Lengua Muerta descansa en un estante, envuelta en lino. Aisha la miró una sola vez y dijo: «Pesa como un hueso de chico». Desde entonces nadie la llama astilla. La llaman «la prueba», y bajan la voz al decirlo.')], { must: true }),
  f('e_hijos_convertidos', from('m_cap3'), c => has(c, 'hijos_convertidos'), [N('Los Hijos del Simurg rezan ahora en la biblioteca, de rodillas, mirando el cristal. Shib reza con ellos y después se queda despierto, mirando el techo. Una vez le dijo a Aisha: «Antes adorábamos lo que el Simurg fue. Ahora adoramos a quien lo lleva puesto. No sé si es lo mismo».')], { pri: 6 }),
  f('e_hijos_aliados', from('m_cap3'), c => has(c, 'hijos_aliados'), [N('Los túneles de los Hijos del Simurg están abiertos para ustedes. Shib les enseñó las marcas: una pluma tallada es agua; dos, salida; tres, «no sigan». Nadie los obliga a rezar. Por eso, algunas noches, rezan igual.')], { pri: 6 }),
  f('e_prueba_templo', from('m_cap3'), c => has(c, 'prueba_templo'), [N('Romain duerme con las órdenes selladas de Kaelen sobre el pecho, bajo la camisa. El papel ya tomó la forma de sus costillas. A veces lo relee para asegurarse de que la firma no cambió. No cambió. Él sí.')], { pri: 6 }),
  f('e_lore_fundacion', from('m_cap3'), c => has(c, 'lore_fundacion'), [N('Desde que el Sabio Anciano les habló de los huesos, caminan por el Bajo de otra manera. Pisan más suave. Bajo cada calle hay más muertos de los que una ciudad puede cargar, y Zaryab los carga igual, sin quejarse, como una madre que no deja que nadie le vea la espalda.')], { pri: 4 }),

  // ───────────────────────── El santuario y el trato con Razul ─────────────────────────
  f('e_santuario_defendido', from('m_cap3'), c => has(c, 'santuario_defendido'), [
    N('Los adeptos todavía cuentan la noche del asalto. En cada versión hay más Qilaat y menos miedo. Apu jura que tumbó a un guardia con la escoba; Cabernet, que fue él, con una botella. Aisha no cuenta nada: friega cada mañana una mancha del umbral que ya no está.'),
    S('Vizir Razul', 'Resistieron. Una ciudad chica dentro de la mía que no se deja tomar. Tres mil años soñé con algo así. No pensé que me tocaría asaltarla.', 'releyendo el informe'),
  ], { must: true }),
  f('e_santuario_saqueado', from('m_cap3'), c => has(c, 'santuario_saqueado'), [N('Volvieron a poner los estantes en pie con tablas de cajón. El altar roto sigue roto: Aisha no deja que nadie lo arregle. «Que se vea», dice. Los seguidores rezan delante de los pedazos. Resulta que un altar partido sirve igual. Resulta que sirve más.')], { must: true }),
  f('e_trato_razul', from('m_cap3', 'm_cap11'), c => has(c, 'trato_razul') && !has(c, 'razul_pacto'), [S('Vizir Razul', '«Mientras no abra la boca», les dije. Llevo la cuenta de las veces que la abren. Van once. Ninguna en la plaza. Es casi conmovedor lo bien que obedecen los que creen que me engañan.', 'pasando las hojas de un cuaderno')], { must: true }),

  // ───────────────────────── Morales del Bajo ─────────────────────────
  f('e_juicio_ejecutado', from('m_cap4'), c => has(c, 'juicio_ejecutado'), [N('En la Ciudadela, un escriba trae la noticia: un guardia llamado Tarek, colgado del arco del acueducto. Razul pide el expediente. Tarek tenía un hijo de seis años. El Vizir firma una orden breve: que al chico le sigan pagando el pan que le pagaban al padre por firmar listas. Después firma otra lista.')], { must: true }),
  f('e_juicio_salvado', from('m_cap4'), c => has(c, 'juicio_salvado'), [N('El guardia que salvaron sigue haciendo la ronda de la Plaza. Cada martes, cuando cambian los turnos, deja caer un papel doblado cerca de la biblioteca. Razul lo sabe desde el primer martes. No lo detiene. Quiere ver cuánto tarda un hombre agradecido en dejar de serlo.')], { must: true }),
  f('e_juicio_justo', from('m_cap4'), c => has(c, 'juicio_justo'), [S('Vizir Razul', 'Me trajeron un guardia vivo y catorce nombres con letra de barrio. Ni soga ni indulto: una lista. Hace siglos que nadie en el Bajo me devuelve el trabajo hecho. Archivala, escriba. Y no la pierdas. Quiero saber quién les enseñó a hacer eso.', 'con la lista entre dos dedos')], { must: true }),
  f('e_nino_castigo', from('m_cap4'), c => has(c, 'nino_castigo'), [N('El chico del escorpión vive. El otro, el dueño del bicho, tiene una marca en la mejilla y ya no juega con nadie. Cuando se cruzan en la calle, los dos bajan la vista a la vez. En el Bajo se aprendió una lección; nadie sabe bien cuál, y por eso se repite.')], { pri: 6 }),
  f('e_nino_secuelas', from('m_cap4'), c => has(c, 'nino_secuelas'), [N('El chico que picó el escorpión cojea. Corre igual, con un saltito torcido, detrás de los demás. Cuando ve pasar a la compañía les levanta la mano. No les reprocha la pierna: les agradece el resto. Es más de lo que la mayoría de los adultos sabría hacer.')], { pri: 6 }),
  f('e_impuesto_matado', from('acto2'), c => has(c, 'impuesto_matado'), [S('Vizir Razul', 'Mataron al recaudador delante del barrio. Ahora el Bajo sabe que el Conclave sangra. Era el secreto más caro de la ciudad y lo regalaron por tres chicos. Quizá el precio fue justo. No me consulten sobre precios: yo pagué uno peor.', 'sin dejar de escribir')], { must: true }),
  f('e_impuesto_pagado', from('acto2'), c => has(c, 'impuesto_pagado'), [N('Quinientas monedas entraron esa semana en el tesoro del Conclave, con una nota al margen: «Bajo Zaryab. Tres niños, no entregados». Razul repasa la cifra con el dedo. Divide. Le da ciento sesenta y seis y fracción. Lo anota en su cuaderno, sin comentario, en una columna que nadie más ha visto.')], { must: true }),
  f('e_impuesto_negociado', from('acto2'), c => has(c, 'impuesto_negociado'), [S('Vizir Razul', 'Negociaron. Mandá al recaudador de vuelta dentro de seis días, con el doble de hombres. No es un castigo: es la tarifa. Quiero saber si saben negociar dos veces.', 'firmando sin leer')], { must: true }),
  f('e_padres_curados', from('m_cap7'), c => has(c, 'padres_curados'), [N('Cinco chicos que ardían de fiebre juegan ahora en la puerta de la biblioteca. Sus madres se turnan para barrer el umbral. Ninguna lo pactó; simplemente amanece barrido. Aisha dice que es la primera vez en años que alguien en el Bajo hace algo sin cobrarlo.')], { must: true }),
  f('e_padres_parcial', from('m_cap7'), c => has(c, 'padres_parcial'), [N('Dos chicos se curaron. Tres no. Las cinco madres siguen viniendo a la biblioteca, las cinco. Las dos que tienen hijos se sientan atrás. Las tres que no, adelante, muy cerca del altar, mirándolo fijo. Nadie les pregunta qué rezan. Nadie se atreve a sentarse en el medio.')], { must: true }),
  f('e_padres_ninguno', from('m_cap7'), c => has(c, 'padres_ninguno'), [N('Hay cinco camas vacías en una choza del Bajo y nadie las desarmó. Las madres no vinieron a maldecir dos veces: con una alcanzó. Cuando la compañía pasa por esa calle, las ventanas se cierran una tras otra, despacio, como párpados.')], { must: true }),

  // ───────────────────────── Djinns del Zoco ─────────────────────────
  f('e_djinn_usado', from('m_cap6'), c => has(c, 'djinn_usado'), [
    S('Vizir Razul', 'Exprimieron a un djinn para alimentar ese cristal. Como nosotros con los molinos, pero más rápido y sin la excusa de la luz. Bienvenidos a la ciudad. Ya pueden opinar sobre ella.', 'a un escriba que no se atreve a contestar'),
    N('En el Zoco, el tenderete de especias todavía huele a ceniza gris. El comerciante ya compró otra lámpara.'),
  ], { must: true }),
  f('e_djinn_comprado', from('m_cap4'), c => has(c, 'djinn_comprado'), [N('El djinn que compraron por doscientas cincuenta monedas sigue en la biblioteca, sin saber qué hacer con las manos. Ocho años moliendo especias. De noche se lo oye girar en el aire sobre sí mismo, despacio, como una piedra de molino que no encuentra el grano.')], { pri: 5 }),
  f('e_jann_espia', from('m_cap4'), c => has(c, 'jann_espia'), [N('El jann que reclutaron pasa el día quieto en un rincón del Zoco, disfrazado de estatua. De noche, en la biblioteca, repite lo que oyó con la voz exacta de quien lo dijo. Es útil. Es también la forma más rápida de perder el sueño: oír a un muerto de hambre por la boca de una piedra.')], { pri: 5 }),
  f('e_jann_enganado', from('m_cap4'), c => has(c, 'jann_enganado'), [S('Vizir Razul', 'La patrulla buscó dos días a un enemigo que no existe. Me mintieron por boca de mi propio jann. Qué bien mienten, para ser creyentes. Que no los persigan por esto. Quiero ver qué más saben inventar.', 'riéndose sin ruido, por primera vez en semanas')], { pri: 6 }),
  f('e_alfombra_viviente', from('m_cap4'), c => has(c, 'alfombra_viviente'), [N('La alfombra nueva de Al-Khush respira. Riyam le dejó agua viva en la trama y Tadhem un poco de viento. Cuando la compañía sube, se estira como un gato al sol. Al-Khush la mira volar desde la puerta del taller y mueve los labios. No suena nada. Pero es una canción.')], { pri: 5 }),
  f('e_alfombra_ardiente', from('m_cap4'), c => has(c, 'alfombra_ardiente'), [N('La alfombra tejida con el ascua del guantelete vuela bien y quema un poco. De noche, en el taller, se oye en sus hilos una voz grave, muy baja, que repite siempre la misma palabra: un nombre. Al-Khush no la oye, porque es sordo. Es, dicen, lo único bueno de serlo.')], { pri: 6 }),
  f('e_alfombra_deuda', from('m_cap4'), c => has(c, 'alfombra_deuda'), [N('Al-Khush tejió la alfombra sin hilo libre, con paciencia y con respeto. Les cobró en reverencias, y sigue cobrando: cada vez que la usan, él inclina la cabeza desde la puerta y espera que ellos la inclinen también. Nunca se le olvidó a nadie. Nadie se atrevería.')], { pri: 4 }),

  // ───────────────────────── Zoco, Plaza y facciones ─────────────────────────
  f('e_caravana_escoltada', from('m_cap4'), c => has(c, 'caravana_escoltada'), [N('Hakim, el de la caravana, cuenta en el Zoco la historia de los ghuls con tanto detalle que ya incluye diálogos que nadie dijo. En su versión, la compañía es más alta. EaNassr lo deja hablar: es la mejor propaganda que tuvo en años, y no le cuesta nada.')], { pri: 4 }),
  f('e_caravana_robada', from('m_cap4'), c => has(c, 'caravana_robada'), [S('Vizir Razul', 'Robaron a una caravana de sobrevivientes. Ahora los mercaderes les ponen precio y yo me ahorro el trabajo. Lo que nunca entendí de los dioses nuevos es por qué empiezan siempre robándoles a los que ya perdieron.', 'con una sonrisa delgada')], { pri: 6 }),
  f('e_hereje', from('m_cap4'), c => has(c, 'hereje_salvado'), [N('El Inquisidor Orm pidió audiencia con el Vizir dos veces, y las dos lo hicieron esperar. Quiere contar que un chico djinn se le escapó entre los estantes de una biblioteca. Razul ya lo sabe. Por eso lo hace esperar: un Inquisidor humillado le resulta más útil que uno con razón.')], { pri: 5 }),
  f('e_inq_aceptado', from('m_cap4'), c => has(c, 'inq_aceptado'), [N('El Inquisidor que desertó duerme en la biblioteca con la espalda contra la pared y una mano en el pecho, donde antes llevaba la insignia. Quemó a ciento tres personas. Los seguidores le dejan la comida en el suelo, cerca, nunca en la mano. Él la come igual y le da las gracias a cada plato.')], { pri: 5 }),
  f('e_inq_samira', from('m_cap4'), c => has(c, 'inq_samira'), [S('Capitana Samira', 'Me entregaron un desertor en vez de matarlo. Lo juzgué delante de mis hombres. No me lo agradezcan: lo que hice con él no tiene nombre bonito. Pero me dejaron decidir. Eso no lo hace nadie con una capitana.', 'en un pasillo del cuartel, a nadie en particular')], { pri: 5 }),
  f('e_monjes_unidos', from('m_cap4'), c => has(c, 'monjes_unidos'), [N('El hermano Ezra se sienta en la última fila de la biblioteca con los ojos blancos cerrados. No le reza a Zahir. Le reza a Kelemvor, en voz baja, y al terminar toca una vez el hombro de Romain. Es su manera de decir que sigue pesando a todos los presentes, cristal incluido.')], { pri: 5 }),
  f('e_monjes_forzados', from('m_cap4'), c => has(c, 'monjes_forzados'), [N('Los nueve monjes de Kelemvor cumplen. Barren, cargan, rezan donde se les dice. Ezra no volvió a hablar. Romain le lleva agua cada tarde y él la acepta sin mirarlo. Hay silencios que son una oración; el de Ezra es una sentencia, y Romain lo sabe.')], { pri: 6 }),
  f('e_ladrones_aceptados', from('m_cap4'), c => has(c, 'ladrones_aceptados'), [N('Nadia y los suyos trajeron a la biblioteca una costumbre: todo lo que se pierde, aparece. Una cuchara, un rosario, una bota. Aparece, eso sí, un poco más gastado. Aisha cuenta los cubiertos cada noche. Empezó a sobrarle uno.')], { pri: 4 }),
  f('e_ladrones_rivales', from('m_cap4'), c => has(c, 'ladrones_rivales'), [N('Las bolsas de los seguidores del culto desaparecen en el Zoco con una regularidad casi religiosa. En su lugar aparece siempre un hueso de dátil. Es la firma de Nadia. No roba para comer: roba para que no la olviden.')], { pri: 4 }),
  f('e_ladron_perdonado', from('m_cap4'), c => has(c, 'ladron_perdonado'), [N('El ladrón al que perdonaron les dejó en el umbral una piedra pulida con una palabra rayada: «grasias». Panchi la guarda en el bolsillo y la frota cuando se enoja, que es seguido. Dice que funciona. Dice que funciona porque está mal escrita.')], { pri: 4 }),
  f('e_info_razul', from('m_cap4', 'm_cap11'), c => H(c, 'nobles_aliados', 'info_razul'), [N('En el Jardín de los Suspiros, tres nobles se sacaron la máscara delante de todos y no se la volvieron a poner. Es un escándalo. Alguien les pasó a ustedes el pliego con los nombres que Razul vigila. En la Ciudadela, el Vizir pidió una copia y tachó con calma los nombres que ya no le servían.')], { must: true }),

  // ───────────────────────── EaNassr y Madam Shub ─────────────────────────
  f('e_ea_aliado', from('acto2'), c => has(c, 'ea_aliado'), [S('EaNassr', 'El espejo me mira distinto desde que volvió. Me muestra lo que hice con mi cara. No es mucho, pero me queda bien. Les debo una, y yo pago siempre. Con intereses, claro: los intereses son lo único sagrado del Zoco.', 'acariciando el marco de bronce')], { must: true }),
  f('e_ea_enemigo', from('acto2'), c => has(c, 'ea_enemigo'), [N('El Espejo de Almas cuelga en la biblioteca y a cada visitante le enseña lo que hizo. EaNassr no volvió a pisar el Bajo. En el Zoco, cuando alguien pregunta por la compañía, sonríe con todos los dientes y cambia de tema. Así afilan un cuchillo los mercaderes.')], { must: true }),
  f('e_espejo_robado', from('m_cap4'), c => has(c, 'espejo_robado'), [N('Madam Shub colgó en su puesto un espejo nuevo, más chico, con un cascabel en el marco. Cuando alguien lo toca, suena. Cuando pasa Zyr\'thar, el cascabel no suena, y Madam Shub la sigue con los ojos hasta que dobla la esquina.')], { pri: 4 }),
  f('e_espejo_comprado', from('m_cap4'), c => has(c, 'espejo_comprado'), [N('Madam Shub se acuerda de quien paga. Cada vez que pasan por el Mercado de las Sombras les hace una seña con la uña pintada: hay mercadería nueva, y ellos la ven primero. Es la clase de amistad que dura mientras alguien tenga monedas. Por ahora alcanza.')], { pri: 4 }),
  f('e_shub_aliada', from('m_cap4'), c => has(c, 'shub_aliada'), [S('Madam Shub', 'Dos frascos de mi reserva, y no les cobro. Sé que no lo entienden. Yo tampoco. Debe ser la edad. O que son los únicos que me miran a los ojos cuando regatean.', 'escondiendo las manos en las mangas')], { pri: 4 }),
  f('e_ea_vendio_silencio', ['m_cap9'], c => has(c, 'ea_vendio_silencio'), [N('«Doce horas de calma», decía el sobre, y EaNassr cumplió: las campanas tardaron en sonar. Lo que no les dijo es a quién le pagó. Esa misma tarde, en la Ciudadela, Razul recibió una bolsa con ochenta monedas y una nota: «Por las molestias». Contó las monedas, las devolvió y se quedó con la nota.')], { must: true }),
  f('e_ea_compro_silencio', ['m_cap9'], c => has(c, 'ea_compro_silencio'), [S('Vizir Razul', 'EaNassr me vendió lo que ellos le vendieron. Les pagó ciento veinte; yo le pagué el doble. No compro lo que dicen: eso ya lo sé. Compro saber que se venden. Es el dato más caro de la ciudad, y siempre está en oferta.', 'guardando un sobre en un cajón')], { must: true }),
  f('e_ea_cubre', from('m_cap4'), c => has(c, 'ea_cubre'), [N('EaNassr compró el silencio del Zoco entero. No dice cuánto le costó. Dice que lo cobra «más adelante», con la misma sonrisa con que se anuncian las tormentas buenas. En el Zoco nadie volvió a pronunciar sus nombres, ni siquiera para venderlos.')], { pri: 5 }),

  // ───────────────────────── Lady Nafisa y los cambiaformas ─────────────────────────
  f('e_nafisa_envenenada', from('acto2'), c => has(c, 'nafisa_envenenada'), [N('Lady Nafisa sobrevivió al té. Tardó una semana en levantarse y otra en volver a sonreír. Ahora sólo bebe agua que se sirve ella misma, de una jarra que nadie más toca. No preguntó quién fue. Una mujer que pone máscaras sabe reconocer las manos debajo de un guante.')], { must: true }),
  f('e_nafisa_en_deuda', from('acto2'), c => has(c, 'nafisa_en_deuda'), [S('Lady Nafisa', 'Me hicieron tomar mi propio té. Dormí un día entero y soñé con ganancias que no eran mías. Les debo una, y lo odio. Las deudas son lo único que no puedo esconder detrás de una máscara.', 'en un salón vacío, con la copa intacta')], { must: true }),
  f('e_nafisa_aval', from('m_cap4'), c => has(c, 'nafisa_aval'), [N('Lady Nafisa dijo sus nombres en voz alta en la corte, y en la corte se repite lo que ella dice. Les abren puertas que antes no tenían picaporte. Lo que nadie sabe es si las abre para dejarlos entrar o para verlos mejor.')], { pri: 5 }),
  f('e_confia_nafisa', ['acto3'], c => has(c, 'confia_nafisa'), [N('Lady Nafisa les manda una invitación por semana. La trae un criado sin máscara, que es su manera de decir «esto es serio». Adentro nunca hay fecha. Sólo una frase: «Cuando todo caiga, yo sabré dónde estaban». No aclara si es una promesa o una advertencia.')], { must: true }),
  f('e_confia_seraphel', ['acto3'], c => has(c, 'confia_seraphel'), [N('Seraphel les enseñó un túnel que no figura en ningún mapa, ni siquiera en los de los Hijos. Termina bajo la Ciudadela. «Para cuando lo necesiten», dijo. No preguntó si lo necesitarían. Los Hijos del Simurg cuentan los días tan bien como Zahir.')], { must: true }),
  f('e_no_confia', ['acto3'], c => has(c, 'no_confia_cambiaformas'), [N('Ni Nafisa ni Seraphel les volvieron a pedir nada. Las dos los saludan con exactamente la misma cortesía. Es inquietante lo parecidas que se vuelven dos rivales cuando descubren que nadie les cree. En el Jardín, los criados apuestan cuál de las dos se mueve primero.')], { must: true }),

  // ───────────────────────── Samira ─────────────────────────
  f('e_samira_justo', ['acto3'], c => has(c, 'samira_justo'), [S('Capitana Samira', 'Me contaron lo justo. No los culpo: yo hago lo mismo con mis superiores. Pero anoté lo que no dijeron, porque eso es lo que se anota en la Guardia. Tengo una página entera de silencios suyos. Es más interesante que la de palabras.', 'repasando su cuaderno a la luz de una vela')], { must: true }),
  f('e_samira_hostil', ['acto3'], c => has(c, 'samira_hostil'), [N('Samira cerró la puerta con cuidado aquella noche, y desde entonces la Guardia patrulla el Bajo con una puntualidad nueva. No es persecución. Es algo peor: oficio. Sobre la mesa de la capitana hay un expediente con sus nombres, y ella dejó de perderlo.')], { must: true }),

  // ───────────────────────── Medinat y el Torneo (Cap. VI) ─────────────────────────
  f('e_apuesta', ['m_cap6', 'm_cap7'], c => has(c, 'apostaste_panchi'), [N('Sesenta monedas apostadas a Panchi, y Panchi perdió. El corredor de apuestas de Medinat guarda la moneda más gastada en un frasco, aparte. Dice que es la única apuesta de su vida hecha por cariño, y que esas no se gastan: se exhiben.')], { pri: 5 }),
  f('e_arena_saboteada', ['m_cap6', 'm_cap7'], c => has(c, 'arena_saboteada'), [N('Aflojaron una cuerda de la jaula y Panchi perdió igual. Sifra lo supo. Antes de irse pasó el pulgar por el mecanismo desmontado y miró hacia la grada, a ustedes, uno por uno. No dijo nada. Una luchadora sin voz sabe decir «no me ayuden» con los ojos.')], { pri: 6 }),
  f('e_carta_leida', ['m_cap7'], c => has(c, 'carta_ellie_leida'), [N('Panchi guarda la carta de Ellie doblada en cuatro, dentro de la venda de lino. No la relee. No le hace falta: «No te pedí que ganaras. Te pedí que volvieras». En el patio de la biblioteca, por las mañanas, practica la guardia con los puños abiertos.')], { must: true }),
  f('e_carta_cerrada', ['m_cap7'], c => has(c, 'carta_ellie_sin_abrir'), [N('La carta sigue cerrada bajo el cinturón de Panchi; el papel ya tomó la curva de su cadera. Cuando se enoja, la toca. Cuando está triste, también. Lejos, en una ciudad que camina, una mujer encapuchada espera la respuesta a una pregunta que nadie leyó.')], { must: true }),
  f('e_medinat_aliado', from('m_cap9'), c => has(c, 'medinat_aliado'), [N('En Medinat al-Rih ya cosen banderas. No tienen colores: los Nasnas no se ponen de acuerdo en ninguno. Pero el Líder lo dijo mirándolos a los ojos, y en Medinat eso vale más que un contrato. Cuando llegue el Eclipse, la ciudad de los olvidados saldrá a la calle. Ya están ensayando cómo.')], { pri: 6 }),

  // ───────────────────────── Dahhak y las Si'lats (Cap. VII) ─────────────────────────
  f('e_dahhak_precio', ['m_cap7', 'm_cap8'], c => has(c, 'dahhak_precio'), [S('Pact Risen', '«Dentro de uno de mis cuellos.» Eso dijo. Era un precio honesto. Lo que me asusta es lo barato que le pareció a una parte de mí.', 'sentado en el borde del tejado, de madrugada')], { pri: 7 }),
  f('e_dahhak_oferta', ['m_cap7', 'm_cap8'], c => has(c, 'dahhak_oferta_pact'), [N('Pact fingió aceptar a Dahhak y el primer golpe fue de ustedes. Fue un buen engaño. Desde entonces, cuando alguien le tiende la mano, a veces la suya se queda en el aire medio segundo de más. Como si una parte de él siguiera caminando hacia el centro de aquella nave.')], { pri: 6 }),
  f('e_dahhak_escuchado', ['m_cap7', 'm_cap8'], c => has(c, 'dahhak_escuchado') && !H(c, 'dahhak_precio', 'dahhak_oferta_pact'), [N('Lo escucharon hasta el final, y Dahhak no mintió. Eso es lo que no se les va. Romain anotó todo en el reverso de una oración: Zahir, el Simurg partido, una mina con hambre. Cuando lo relee no sabe qué le dio más miedo, la mentira que esperaba o la verdad que oyó.')], { pri: 5 }),
  f('e_secreto_dahhak', ['m_cap7', 'm_cap8'], c => has(c, 'secreto_dahhak'), [S('Zahir', 'Dahhak les dijo que el Simurg se partió solo. Puede ser. Yo sólo recuerdo el frío, y que no tenía manos para abrazarme. Ustedes tienen manos tibias. No saben la suerte que tienen.', 'desde el reflejo de un charco, muy bajo')], { pri: 7 }),
  f('e_pact_rechaza', ['m_cap8'], c => has(c, 'pact_rechaza_dahhak'), [N('Dahhak se pasea por la Iglesia hablando solo. A veces dice el nombre de Pact como quien prueba una fruta que no llegó a madurar. «En otro siglo», repite. Las Si\'lats le llevan la comida y lo oyen contar los años que faltan, uno por uno, con paciencia de abuelo.')], { must: true }),
  f('e_pact_oyo', ['m_cap8'], c => has(c, 'pact_oyo_dahhak'), [N('Pact escuchó a Dahhak una hora entera. No dijo que sí. Ahora, cuando duerme, la corona de fuego invertido le aparece sobre la frente un instante, y se apaga. Rabb lo vio dos veces y no se lo contó. Hay secretos que uno guarda por el otro, no contra él.')], { must: true }),
  f('e_sabe_fragmentos', ['m_cap7', 'm_cap8', 'm_cap9'], c => has(c, 'sabe_fragmentos'), [N('«Casi», dijo Zahir. Desde entonces el cristal se enfría un grado cuando alguien pronuncia la palabra Simurg. Rabb hace la prueba de noche: dice el nombre, se pone la mano en el pecho, cuenta. Siempre baja. Nunca sube. Dejó de decirlo.')], { pri: 5 }),
  f('e_silats_cuellos', ['m_cap7', 'm_cap8'], c => has(c, 'silats_cuellos'), [N('«Cada cuello es una persona que no terminó la frase.» Romain no deja de pensarlo. Empezó a terminar en voz baja las frases de los demás cuando se quedan a medias, por si acaso. Nadie se lo pidió. Panchi, que interrumpe siempre, lo notó, y por primera vez en su vida termina las suyas.')], { pri: 5 }),
  f('e_silats_azuran', ['m_cap7', 'm_cap8'], c => has(c, 'silats_azuran'), [N('Azuran pidió que lo partieran, dijeron las Si\'lats, porque había visto lo que había que ver y no quería recordarlo entero. Pact no preguntó qué vio. Pero ahora, cuando alguien le cuenta algo terrible, escucha hasta el final sin apartar la vista. Como quien practica.')], { pri: 5 }),
  f('e_silats_guian', ['m_cap8', 'm_cap9'], c => has(c, 'silats_guian'), [N('Las Si\'lats siguen guiando. No a ustedes: a los que vienen detrás. En las galerías que no figuran en ningún plano dejaron tazas de barro llenas en cada repisa. Quien beba, dicen, llegará con la boca limpia a lo que tenga que llegar.')], { pri: 3 }),
  f('e_cena_cocina', ['m_cap8', 'm_cap9'], c => has(c, 'cena_cocina'), [N('Desde la cena, Aisha les deja cada tarde un cuchillo junto a la tabla del pan. No dice nada. Si ellos cortan, ella amasa. Si no, corta y amasa. Es la conversación más larga que tienen, y la más sincera: nadie miente con las manos en la harina.')], { pri: 5 }),
  f('e_cena_escucha', ['m_cap8', 'm_cap9'], c => has(c, 'cena_escucha'), [N('Cabernet sigue contando lo del vino sin alcohol y el Inquisidor. Ahora la historia tiene otro final, y otro más. Apu ya no dice que es mentira: dice «esa no, la otra». Los seguidores se las saben todas de memoria. Así empiezan las escrituras: con alguien que escuchó.')], { pri: 5 }),

  // ───────────────────────── Razul en la mesa (Cap. VIII) y después ─────────────────────────
  f('e_razul_sin_agua', ['m_cap8'], c => has(c, 'razul_sin_agua'), [N('El vaso de esa noche no se lo sirvió nadie: se lo sirvió él. En el cuaderno anotó: «No me dieron agua. Hicieron bien». Debajo, con la misma pluma: «Yasmin tampoco tuvo». Después tachó la primera línea. La segunda no.')], { must: true }),
  f('e_razul_decepcion', ['m_cap8'], c => has(c, 'razul_decepcion'), [
    S('Vizir Razul', 'Les ofrecí una salida y no supieron pedirla. No es un reproche. Yo tampoco supe pedir nada, la única vez que importaba.', 'al escriba, mientras se quita los guantes'),
    N('Esa noche el Vizir no anotó nada. Es la primera página en blanco de su cuaderno en tres mil años.'),
  ], { must: true }),
  f('e_razul_pajaro', ['m_cap9'], c => has(c, 'razul_pajaro'), [N('En el limbo, lejos de todos, Zahir se miró en el agua quieta y ladeó la cabeza. Se detuvo a medio gesto. Lo corrigió. Volvió a ladearla, más despacio, de otra manera, como un actor que ensaya frente al espejo el modo de no parecerse a sí mismo.')], { must: true }),
  f('e_razul_historia', ['m_cap9', 'acto3'], c => has(c, 'razul_historia'), [N('Aquella noche el Vizir escribió en su cuaderno la pregunta que le hicieron en la biblioteca: «¿Y vos? ¿También empezaste así?». Debajo, tres respuestas tachadas. Debajo de las tachadas, una sola palabra sin tachar, tan chica que el escriba que la vio a la mañana no supo si decía «no» o «yo».')], { pri: 7 }),
  f('e_razul_pregunta', ['m_cap9', 'acto3'], c => has(c, 'razul_pregunta'), [S('Vizir Razul', 'Me preguntaron por qué no los detuve antes. Era una pregunta de chico y la contesté como a un adulto. Tendría que haberla contestado como a un chico: «Porque estaba cansado». Habría sido la primera verdad entera que digo en mil años.', 'a la ventana, de noche')], { pri: 7 }),
  f('e_razul_yasmin', ['m_cap9', 'acto3'], c => has(c, 'razul_yasmin'), [N('Desde la visita del Vizir, Aisha deja cada mañana un dátil en el alféizar de la cocina. No dice para quién. Los pájaros no lo tocan; las hormigas tampoco. Al anochecer lo retira, lo envuelve en un trapo limpio y lo guarda en una caja que nadie tiene permiso de abrir.')], { pri: 5 }),
  f('e_razul_reloj', ['m_cap9', 'acto3', 'm_cap11'], c => has(c, 'razul_reloj'), [N('El reloj de arena de bronce sigue sobre la mesa de la biblioteca. Farid se sienta a mirarlo caer. Descubrió que, si uno lo mira fijo, los granos caen más despacio. Nadie le cree. Nadie se atreve, tampoco, a dejar de mirarlo cuando él se va a dormir.')], { pri: 7 }),
  f('e_razul_cobro', ['m_cap9', 'acto3', 'm_cap11'], c => has(c, 'razul_cobro'), [S('Vizir Razul', 'Cobré. Me dolió menos de lo que esperaba y más de lo que debía. Escriba: anotá que pagaron sin pedir rebaja. La gente que paga sin regatear todavía cree en algo. Es lo único que nunca supe cobrarle a nadie.', 'dejando el reloj vacío sobre la mesa')], { must: true }),

  // ───────────────────────── Acto II tardío: tigre, cementerio ─────────────────────────
  f('e_tigre_libre', from('m_cap7'), c => has(c, 'tigre_libre'), [N('En el Pico del Viento, los Nómadas del Vacío ven pasar a veces una sombra con alas entre las nubes de tormenta. No baja. Pero el Roc ciego levanta la cabeza en su nido cada vez que truena, y los viejos dicen que es porque alguien, allá arriba, le avisa que todavía hay cielo.')], { must: true }),
  f('e_tigre_muerto', from('m_cap7'), c => has(c, 'tigre_muerto'), [N('La garra del tigre de tormenta cuelga en la biblioteca y chisporrotea los días de lluvia. Los chicos la tocan con un dedo para sentir el cosquilleo. Los Nómadas, cuando la ven, no dicen nada. Murió mirando el cielo del que cayó. Ellos, que miran el cielo todo el día, no lo olvidan.')], { must: true }),
  f('e_nomadas', from('m_cap7'), c => has(c, 'nomadas_ayuda'), [N('El tigre alado duerme en el patio de la biblioteca y ocupa medio patio. Ronronea con truenos. Los Nómadas del Vacío mandan cada semana un odre de leche de camella para él y una frase para ustedes: «Cuando necesiten el desierto, el desierto vendrá». Es la primera vez que la dicen fuera de su tribu.')], { pri: 6 }),
  f('e_ejercito_descansa', from('m_cap7'), c => has(c, 'ejercito_descansa'), [N('En el Cementerio Olvidado, las lápidas del ave quemada amanecen ahora con flores. Nadie las lleva: crecen. Romain fue una vez a mirar y volvió en silencio. Sólo dijo que el polvo estaba tibio, y que Kelemvor, por fin, había anotado unos cuantos nombres en su libro.')], { must: true }),
  f('e_ejercito_culto', from('m_cap7'), c => has(c, 'ejercito_culto'), [S('Vizir Razul', 'Un ejército de muertos sin nombre marcha ahora detrás de un cristal. Los borramos de los libros para que nadie los convirtiera en bandera. Y llegan ustedes y les dan una orden. Qué rápido aprenden los dioses nuevos a no dejar descansar a nadie.', 'mirando el cementerio desde la torre')], { must: true }),

  // ───────────────────────── Acto III ─────────────────────────
  f('e_farid_ve', ['acto3'], c => has(c, 'farid_ve'), [S('Farid', 'Ya está más cerca. La mano. Tiene un anillo que no es de nadie. Y hay una puerta que se abre sola cuando nadie la empuja. No da miedo. Da… frío de mañana temprano.', 'dibujando con el dedo en el polvo de los escalones')], { must: true }),
  f('e_farid_protegido', ['acto3', 'm_cap11'], c => has(c, 'farid_protegido'), [N('Farid dejó el arpa en un rincón, envuelta en una manta. Juega con los otros chicos, pierde a propósito, se ríe fuerte. Aisha lo mira con alivio. Sólo de noche, dormido, mueve los dedos sobre la manta, tres notas, y se detiene antes de la cuarta. Nadie lo despierta.')], { must: true }),
  f('e_farid_sabe', ['m_cap11', 'm_cap12'], c => has(c, 'farid_sabe'), [N('Farid sabe que el Lich cantaba para él, y no tiene miedo. Empezó a cantar la nana de Qadir de noche, para quien quiera oírla. Aisha escucha detrás de la puerta. No sabe si su hijo se está curando o se está convirtiendo en otra cosa. Escucha igual.')], { must: true }),
  f('e_pista_farid', from('m_cap3', 'm_cap11'), c => has(c, 'pista_farid'), [N('«Un hombre de dientes blancos hace preguntas sobre un chico enfermo.» Se lo dijo alguien a quien perdonaron, antes de huir. Desde entonces Aisha no deja que Farid toque el arpa en la esquina: lo hace tocar adentro, con la ventana cerrada. El barrio extraña la música. El hombre de dientes blancos, también.')], { pri: 5 }),
  f('e_mazhar_tomo', ['acto3', 'm_cap11'], c => has(c, 'mazhar_tomo'), [N('El Tomo de Maunator se hizo ceniza en las manos de Romain. Él la guarda igual, en una bolsa de cuero, junto a la balanza vacía. Dice que un libro que cumplió su único trabajo merece el mismo respeto que un hombre que cumplió el suyo. Nadie discute. Nadie toca la bolsa.')], { pri: 6 }),
  f('e_conoce_defensas', ['acto3', 'm_cap11'], c => has(c, 'conoce_defensas'), [N('Zyr\'thar dibuja en la mesa, con vino aguado, lo que vieron el día del juicio: las runas giratorias, los puestos de los golems, las rondas. Se acuerdan de todo. Lo que no saben es que Razul no cambió ni una runa desde entonces. Le pareció descortés con quienes se tomaron la molestia de aprenderlas.')], { pri: 7 }),
  f('e_info_ciudadela', ['acto3', 'm_cap11'], c => has(c, 'info_ciudadela'), [N('Alguien les dejó dicho, en un papel doblado en cuatro, que la Ciudadela tiene tres escaleras y que la del Vizir no tiene guardias. Lo leen dos veces. Lo que asusta no es el dato. Es que, en tres mil años, nadie haya tenido el valor de comprobarlo.')], { pri: 6 }),
  f('e_zahir_pregunta', ['m_cap11'], c => has(c, 'zahir_pregunta'), [S('Zahir', 'Me preguntaron qué soy. Soy lo que queda de algo que fue enorme y tuvo frío. Cuando el último fragmento esté en su sitio, se los voy a mostrar entero. Les va a gustar. Creo.', 'entre los pedestales, despacio, con algo de timidez')], { must: true }),
  f('e_zahir_rechazo_2', ['m_cap11'], c => has(c, 'zahir_rechazo_2'), [N('Desde que le dijeron que no necesitaban sus gracias, el cristal late con otro compás, más puntual, como un empleado que vuelve al trabajo después de una ofensa. Zahir no volvió a dar las gracias. Volvió a dar órdenes. Es más fácil, para los dos.')], { must: true }),
  f('e_simbolo_gusano', ['m_cap11'], c => has(c, 'sabe_simbolo_gusano'), [N('El círculo con el ojo hundido. Lo vieron bajo el Consulado; lo vieron en la mina. Ahora lo buscan sin querer en cada pared del Bajo, y a veces lo encuentran donde no está: en un nudo de la madera, en una mancha de humedad. Es lo que pasa cuando uno aprende cómo respira algo que no muere.')], { pri: 6 }),
  f('e_gusano_huida', from('m_cap3'), c => has(c, 'gusano_huida'), [N('Escaparon del Gusano de Cabeza de Martillo por los túneles. Desde entonces, cuando una taza tiembla en la mesa, todos se quedan quietos y cuentan. Panchi dice que es ridículo. Panchi es el primero en dejar de respirar.')], { pri: 5 }),

  // ───────────────────────── La noche antes del Eclipse (tras Cap. XII) ─────────────────────────
  f('e_abril_salvada', ['m_cap12'], c => has(c, 'abril_salvada'), [S('Abril', 'Volvieron. No tenían por qué. Dibujé el tercer nivel entero, de memoria, para que nadie más tenga que bajar a buscar a nadie. Decían que mi papá se fue con otra mujer. Era la mina. Ya la tengo en el papel. Ya no me asusta.', 'en su puesto de Medinat, con el cuaderno bajo el brazo')], { must: true }),
  f('e_abril_perdida', ['m_cap12'], c => has(c, 'abril_perdida'), [N('El cuaderno de Abril sigue colgado del clavo, en el Bajo. Nadie lo descuelga. En Medinat, su puesto de dulces amanece cerrado, y alguien dejó en el mostrador un puñado de dátiles, por si vuelve con hambre. En el tercer nivel de la mina, dicen los que no bajan, una lámpara sigue encendida.')], { must: true }),
  f('e_kethras_pacto', ['m_cap12'], c => has(c, 'kethras_pacto'), [N('Kethras cumplió. Al día siguiente lo interrogaron tres escribas y no había visto nada. Lo dijo tres veces, con la misma voz y la misma cara. Después volvió a su sótano ajeno, se sirvió una copa y brindó, solo, por la única promesa que no le dio vergüenza cumplir.')], { must: true }),
  f('e_kethras_neutral', ['m_cap12'], c => has(c, 'kethras_neutral'), [S('Kethras', 'Les dije que lo sabía desde que firmé. No les dije que firmé con tinta. Alguien me aconsejó una vez no firmar nada con tinta. No le hice caso. Me alegra que ustedes sean menos tercos que yo.', 'apoyado en el bastón, en una escalera vacía')], { must: true }),
  f('e_kethras_burlado', ['m_cap12'], c => has(c, 'kethras_burlado'), [N('«¿Quieren saber quién cegó al Juez?» Kethras giró la cabeza un instante, y alcanzó. Ahora pasa las noches preguntándose si Seraphel lo sabía de verdad o sólo sabía qué pregunta lo haría girar. Las dos respuestas le parecen igual de humillantes. Empezó a admirarla.')], { must: true }),
  f('e_kethras_combate', ['m_cap12'], c => has(c, 'kethras_combate'), [N('Kethras gastó su Bola de Fuego contra ustedes y ustedes siguieron de pie. Se retiró sin apuro, con una quemadura en la manga y la cara de quien anota un error en un libro de cuentas. «Qué previsibles», había dicho. Ahora lo repite, con menos seguridad, cuando se mira al espejo.')], { must: true }),
  f('e_romain_ve', ['m_cap12'], c => has(c, 'romain_ve'), [N('Romain pesó a Razul con los ojos abiertos. Esa noche, por primera vez desde el templo quemado, dejó la balanza destapada junto a la cama. Los platillos no se movieron. Él tampoco. Durmió de un tirón, como duermen los que miraron algo de frente y no se murieron por eso.')], { pri: 7 }),
  f('e_vispera_romain', ['m_cap12'], c => has(c, 'vispera_romain'), [N('La balanza de Romain sigue en la capilla, donde la dejó la víspera de subir a la Ciudadela. Fue lo primero que miró aquella mañana, como había prometido. Esta noche vuelve a mirarla. Ya no está vacía del mismo modo: ahora le falta algo concreto, y eso, dice, es casi un consuelo.')], { must: true }),
  f('e_vispera_pact', ['m_cap12'], c => has(c, 'vispera_pact'), [N('«Si muero mañana, que la use alguien más», dijo Pact la víspera de la Ciudadela. No murió. Esta noche vuelve a tener la corona entre las manos y la gira despacio, como quien busca por dónde se abre una caja que no tiene tapa.')], { must: true }),
  f('e_vispera_panchi', ['m_cap12'], c => has(c, 'vispera_panchi'), [S('Panchi', 'Dije «traelo o no vengas», y vine. Así que alguien lo va a traer. Mañana. A mí no me miren: yo sólo me vendo los puños.', 'vendándose otra vez, aunque las vendas están nuevas')], { must: true }),
  f('e_vispera_aisha', ['m_cap12'], c => has(c, 'vispera_aisha'), [N('El dibujo de Farid, un pájaro muy torcido con seis personas encima, está clavado sobre la puerta de la biblioteca. Aisha le hizo un marco de cañas. Esta noche, al pasar debajo, cada uno levanta la vista y cuenta las figuras. Nadie cuenta en voz alta.')], { must: true }),

  // ───────────────────────── Tratos del Oráculo (ambiente menor) ─────────────────────────
  f('e_demonio_pacto', from('m_cap3'), c => has(c, 'demonio_pacto'), [N('El demonio de los sacrificios prometió fuerza sin precio, y por ahora cumple. Pero los perros del Bajo ladran cuando la compañía pasa de noche, y la leche de Aisha se corta dos días antes de tiempo. En Zaryab los precios siempre llegan. A veces, primero, mandan aviso.')], { pri: 6 }),
  f('e_recuerdo_vendido', from('m_cap3'), c => has(c, 'recuerdo_vendido'), [N('Uno de ustedes vendió un recuerdo de infancia a un místico del trueque. Ahora a veces se descubre sonriendo frente a un patio cualquiera, una higuera, un pozo, sin saber por qué. El hueco es tibio. Es lo único que queda de una risa: la temperatura.')], { pri: 5 }),
  f('e_pacto_roto', from('m_cap3'), c => has(c, 'pacto_roto_1'), [N('El hombre al que Rabb le arrancó una página del contrato vende agua en la Plaza Vieja. Es un oficio pobre. Lo hace silbando. A Rabb le regala un vaso cada vez que pasa, y Rabb lo toma despacio, preguntándose quién le arrancará algún día la página a él.')], { pri: 5 }),
  f('e_amigo_ser', from('m_cap3'), c => has(c, 'amigo_ser'), [N('«No firmen nada con tinta», les dijo el ser sin nombre después de una hora de hablar de nubes y de muertos. Desde entonces Joren firma los recibos del Zoco con una cruz de carbón. Los mercaderes protestan. Él no explica. Hay consejos que uno sigue justamente porque no los entiende.')], { pri: 4 }),
  f('e_fantasma', from('m_cap3'), c => has(c, 'fantasma_redencion'), [N('Enterraron el anillo bajo el ciprés, como pidió la voz. Desde entonces, en ese rincón, nadie siente frío de noche. Los enamorados del barrio empezaron a citarse ahí sin saber por qué. Es lo que deja un fantasma cuando por fin se va: un lugar donde da gusto quedarse.')], { pri: 4 }),
  f('e_prisionero', from('m_cap3'), c => has(c, 'prisionero_liberado'), [N('«El hombre del ojo que no ve.» Es todo lo que dijo el prisionero antes de correr. Lo oyeron dos veces más desde entonces: una en boca de un borracho, otra en boca de Zahir, en sueños. Ninguno de los dos supo decir dónde vive. Los dos bajaron la voz.')], { pri: 4 }),
  f('e_consejo_mistico', from('m_cap3'), c => has(c, 'consejo_mistico'), [N('El místico del futuro les dijo que les vería la cara en un espejo roto, y que no era mentira. Desde entonces Zyr\'thar rompe sin querer todos los espejos que toca. Dice que es casualidad. Ya van cuatro.')], { pri: 4 }),
  f('e_reliquia', from('m_cap3'), c => has(c, 'reliquia_princesa'), [N('Prometieron buscar la reliquia de una princesa que sonríe como un espejo roto. No la buscaron. Ella lo sabe. Cada tanto, en el agua de un balde, aparece su reflejo, con la paciencia de quien esperó siglos y puede esperar unos días más.')], { pri: 4 }),
  f('e_medico', from('m_cap3'), c => has(c, 'medico_aliado'), [N('El médico errante volvió, como había prometido. Curó a dos seguidores de una tos y a un tercero de un miedo. No quiso cobrar. Dijo que con el cristal del pecho ya pagaban bastante, y antes de irse les tomó el pulso a todos, uno por uno, con el ceño fruncido.')], { pri: 4 }),
  f('e_marca_templo', from('m_cap3'), c => has(c, 'marca_templo'), [N('La marca del templo les arde en la piel cuando cruzan una plaza llena. Todo el mundo ve lo que son. Los mercaderes les cobran más; los mendigos, menos. Un chico los siguió una tarde entera sólo para preguntarles si la marca duele. Le dijeron que no. Mienten bien.')], { pri: 5 }),
  f('e_vampiro', from('m_cap3'), c => has(c, 'vampiro_info'), [N('El vampiro que buscaba redención les dijo dónde duermen los Inquisidores. Desde entonces, cada tanto, aparece en la puerta de la biblioteca una flor negra sin tallo. No pide entrar. Sabe que no se lo permitirían, y parece que eso, justamente, le hace bien.')], { pri: 3 }),
  f('e_bardo', from('m_cap3'), c => has(c, 'secretos_bardo'), [N('El secreto del Conclave que les dijo el bardo encantado les costó una pesadilla, y la pesadilla vuelve. Siempre la misma: una sala de cuentas, una pluma que escribe sola, un nombre que no alcanzan a leer. Al despertar, alguno tararea la melodía del laúd sin querer.')], { pri: 3 }),
  f('e_alfombra_defectuosa', from('m_cap3'), c => has(c, 'alfombra_defectuosa'), [N('La alfombra que compraron a mitad de precio vuela tres metros y los deja caer con cierta elegancia. Panchi la usa de felpudo. Ella se ofende, y cada tanto se enrolla sola y se va a dormir al tejado, donde nadie la pisa.')], { pri: 3 }),
];
